notes:
NodeMCU karşılığı (gerçek MQTT, simülatörde ÇALIŞMAZ ve doğrulanmadı): ESP8266'yı tek başına programlarsan Wi-Fi ve MQTT kendi kodunda olur. Örnek iskelet:
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
const char* AG = "ag_adi";  const char* PAROLA = "parola";  const char* BROKER = "192.168.1.10";
WiFiClient wifi;  PubSubClient mqtt(wifi);
const int ROLE1 = D1;   // LOW'da çeken röle modülü
void gelen(char* konu, byte* veri, unsigned int boy) {
  if (boy > 0 && String(konu) == "ev/salon/role/1") { digitalWrite(ROLE1, veri[0] == '1' ? LOW : HIGH); }
}
void baglan() {
  while (!mqtt.connected()) {
    if (mqtt.connect("salon-dugumu")) { mqtt.subscribe("ev/salon/role/1"); } else { delay(2000); }
  }
}
void setup() {
  pinMode(ROLE1, OUTPUT);  digitalWrite(ROLE1, HIGH);
  WiFi.begin(AG, PAROLA);
  while (WiFi.status() != WL_CONNECTED) { delay(500); }
  mqtt.setServer(BROKER, 1883);  mqtt.setCallback(gelen);
}
void loop() {
  if (!mqtt.connected()) { baglan(); }
  mqtt.loop();
  // her 5 saniyede: mqtt.publish("ev/salon/sicaklik", "24.0");
}
Bu kod ESP8266 çekirdeğiyle (ESP8266WiFi.h) ve PubSubClient kütüphanesiyle Arduino IDE'de derlenir; broker olarak yerel bir Mosquitto sunucusu kullanılabilir.
